// Trang quản lý theo bộ truyện: mọi tin nhắn và nút bấm gửi bot đều vào đây qua node Telegram (webhook).
// Mỗi truyện đăng YouTube trước; TikTok của truyện chỉ gửi khi đã bấm "Bắt đầu TikTok" (dòng tiktok:<job_id> = on ở tab CaiDat).
// Đọc Sheet, làm việc được yêu cầu, rồi trả ra danh sách việc cho các nhánh phía sau theo trường op:
// status / retry / flag ghi Sheet, tg gọi Telegram, tgsend gửi tin mới (ghi vào TelegramLog để dọn lúc 0h),
// tiktok / youtube chạy workflow gửi video. Các nhánh chạy lần lượt từ trên xuống trên canvas: ghi Sheet xong mới gọi workflow.
const cfg = $('Cấu hình').first().json;
const update = $('Telegram').first().json;
const q = update.callback_query;
const m = update.message;
const chatId = q?.message?.chat?.id ?? m?.chat?.id;
// Node Telegram đã chỉ nhận tin trong cuộc trò chuyện của bạn; kiểm tra lại cho chắc.
if (chatId === undefined || String(chatId) !== String(cfg.chat_id)) return [];

const TZ = 'Asia/Ho_Chi_Minh';
const errorText = (e) => (typeof e === 'string' ? e : e?.message ?? JSON.stringify(e));
// Tab CaiDat chưa có (chưa từng bấm nút nào ghi vào đó) thì mọi thứ để mặc định; lỗi khác thì không đoán.
const missingTab = (e) => /not found|unable to parse range/i.test(errorText(e));
const read = $('Đọc Sheet').all().map((i) => i.json);
const flagRows = $('Đọc cài đặt').all().map((i) => i.json);
const readError = read.find((r) => r.error)?.error ?? flagRows.map((r) => r.error).find((e) => e && !missingTab(e));
const all = read.filter((r) => r.id && r.job_id);
// Dòng "removed" là video không còn trong truyện (dựng lại khác số phần): không tính.
const rows = all.filter((r) => r.status !== 'removed');
// Tab CaiDat ghi nối tiếp, dòng sau cùng của mỗi key là giá trị đang dùng.
const flags = {};
for (const f of flagRows) if (f.key) flags[f.key] = String(f.value ?? '');

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > n ? `${t.slice(0, n - 1).trimEnd()}…` : t;
};
const at = (v) => {
  const d = DateTime.fromISO(String(v ?? ''));
  return d.isValid ? d.setZone(TZ) : null;
};
const today = $now.toISODate();
const when = (d) => (d ? d.toFormat(d.toISODate() === today ? 'HH:mm' : 'HH:mm dd/MM') : '?');
const clock = $now.toFormat('HH:mm');
const length = (sec) => {
  const s = Math.round(Number(sec) || 0);
  const pad = (n) => String(n).padStart(2, '0');
  return s >= 3600 ? `${Math.floor(s / 3600)}:${pad(Math.floor(s / 60) % 60)}:${pad(s % 60)}` : `${Math.floor(s / 60)}:${pad(s % 60)}`;
};
const own = (map, key) => (Object.hasOwn(map, key) ? map[key] : undefined);
// Tên ngắn của truyện, như storyNameFromTitle của Story Studio: dòng đầu caption TikTok ("Tên truyện | Phần 1/5"),
// hoặc tên rút từ tiêu đề khi caption cũ còn tiêu đề dài.
const TITLE_TAGS = /\[[^\]]*\]|【[^】]*】|\([^)]*\)|#\S*|\b(cre|credit|nguồn|source)\s*:.*$|\d[\d.,]*\s*[kmb]?\s*(views?|lượt xem|reactions?|likes?|lượt thích|comments?|bình luận|shares?)/giu;
const TITLE_SEPARATORS = /\s+[-–—]\s+|\s*[|·•]\s*|[:.]\s+/u;
const TITLE_NOISE = /^(\d+|full( bộ)?|trọn bộ|\d+\s*(phút|giờ|tiếng)|(tập|phần|part|ep)\s*\d+|.*\b(audio|official|channel|radio|podcast)\b.*|truyện (ngắn|audio|ma|hay|kể|kinh dị|ngôn tình|cổ tích|trinh thám)\b.*)$/iu;
const nameFromTitle = (title) => {
  const pieces = String(title ?? '').replace(TITLE_TAGS, ' ').split(TITLE_SEPARATORS).map((s) => s.replace(/["“”'‘’]/g, '').trim()).filter(Boolean);
  return pieces.find((s) => !TITLE_NOISE.test(s)) ?? pieces.join(' ');
};
const PART_SUFFIX = /\s*(\|\s*Phần\s*\d+\s*\/\s*\d+|\(trọn bộ\))\s*$/iu;
const NAME_MAX = 45;
/** Tên ngắn của truyện của một dòng trong Sheet. Dòng YouTube không lấy caption (đó là mô tả YouTube). */
const shortName = (r) => {
  const line = r.format === 'youtube' ? '' : String(r.post_description ?? '').split('\n')[0].replace(PART_SUFFIX, '').trim();
  for (const c of [line, nameFromTitle(line), nameFromTitle(r.post_title), nameFromTitle(r.title), String(r.title ?? '').trim()]) {
    if (c && c.length <= NAME_MAX) return c;
  }
  const t = line || String(r.title || r.id || '');
  return t.length > NAME_MAX ? `${t.slice(0, NAME_MAX - 1).replace(/\s+\S*$/, '')}…` : t;
};

// ── Video và truyện, theo đúng quy tắc của hai workflow gửi video ─────────────
const P = {
  tiktok: { name: 'TikTok', schedule: cfg.lich_tiktok, lockMin: 30, where: 'hộp thư TikTok' },
  youtube: { name: 'YouTube', schedule: cfg.lich_youtube, lockMin: 180, where: 'kênh YouTube' },
};
const platform = (r) => (r.format === 'youtube' ? 'youtube' : 'tiktok');
const rank = (r) => (r.kind === 'full' ? Infinity : Number(r.part || 0));
const order = (a, b) => String(a.job_id).localeCompare(String(b.job_id)) || rank(a) - rank(b);
const due = (r) => !r.scheduled_at || DateTime.fromISO(String(r.scheduled_at)) <= $now;
// Đang gửi: khoá chưa quá 30 phút (TikTok) hoặc 3 giờ (YouTube). Quá hạn là bị kẹt, xem ở màn hình Video lỗi.
const sending = (r) => r.status === 'posting' && !!at(r.posted_at) && $now.diff(at(r.posted_at), 'minutes').minutes < P[platform(r)].lockMin;
const stuck = (r) => r.status === 'posting' && !sending(r);
const FINAL = ['posted', 'skipped'];

// Trạng thái trong bộ nhớ đổi (ghi đã đăng, bắt đầu TikTok…) thì tăng version để tính lại các kết quả đã nhớ.
let version = 0;
const memo = (fn) => {
  const cache = new Map();
  return (...args) => {
    const key = `${version}|${args.join('|')}`;
    if (!cache.has(key)) cache.set(key, fn(...args));
    return cache.get(key);
  };
};
const byJob = new Map();
for (const r of rows) {
  if (!byJob.has(r.job_id)) byJob.set(r.job_id, []);
  byJob.get(r.job_id).push(r);
}
for (const list of byJob.values()) list.sort(order);
const jobs = [...byJob.keys()].sort();
const rowsOf = (job, p) => (byJob.get(job) ?? []).filter((r) => !p || platform(r) === p);
const nameOf = (job) => {
  const list = rowsOf(job);
  return shortName(list.find((r) => platform(r) === 'tiktok') ?? list[0] ?? { id: job });
};
const partName = (r) => (r.part ? `phần ${r.part}` : 'trọn bộ');
// Video trọn bộ ghi "Trọn bộ" khi cùng nền tảng của truyện còn có các phần.
const fullName = (r) => r.kind === 'full' && rowsOf(r.job_id, platform(r)).length > 1;
const label = (r) => `${nameOf(r.job_id)}${r.part ? ` · Phần ${r.part}/${r.total_parts}` : fullName(r) ? ' · Trọn bộ' : ''}`;
// TikTok của truyện: bấm Bắt đầu (on) hoặc Dừng (off); truyện đã gửi TikTok từ trước khi có nút này coi như đã bắt đầu.
const ttFlag = (job) => flags[`tiktok:${job}`];
const ttStarted = memo((job) => ttFlag(job) === 'on'
  || (ttFlag(job) !== 'off' && rowsOf(job, 'tiktok').some((r) => ['inbox', 'posted', 'posting', 'skipped'].includes(r.status))));
// Bản trọn bộ TikTok chỉ gửi khi không còn phần nào của truyện chưa đăng (kể cả phần đang lỗi chờ gửi lại).
const partsLeft = (r) => rowsOf(r.job_id, 'tiktok').some((x) => x.kind !== 'full' && ['pending', 'posting', 'inbox', 'error'].includes(x.status));
const ready = (r) => due(r) && (platform(r) === 'youtube' || (ttStarted(r.job_id) && (r.kind !== 'full' || !partsLeft(r))));
const pendingOf = memo((p, job) => (job ? rowsOf(job, p) : rows.filter((r) => platform(r) === p).sort(order)).filter((r) => r.status === 'pending'));
const nextOf = memo((p, job) => pendingOf(p, job).find(ready) ?? null);
const inboxToday = () => rows.filter((r) => platform(r) === 'tiktok' && r.status === 'inbox' && at(r.posted_at)?.toISODate() === today).sort(order);
const problems = () => rows.filter((r) => r.status === 'error' || stuck(r)).sort(order);
const isAuto = (p) => flags[`${p}_auto`] !== 'off';
const byId = (id) => all.find((r) => String(r.id) === String(id));
const isOpen = (job) => rowsOf(job).some((r) => !FINAL.includes(r.status));
const ytDone = (job) => rowsOf(job, 'youtube').every((r) => FINAL.includes(r.status));

// ── Việc cần làm ───────────────────────────────────────────────────────────────
const ops = [];
const notice = [];
let answer = '';
let runTikTok = null;
let runYouTube = null;

const setStatus = (r, status) => {
  r.status = status;
  r.posted_at = status === 'posted' ? $now.toISO() : '';
  version++;
  ops.push({ op: 'status', id: r.id, status, posted_at: r.posted_at });
};
// Video vừa gọi workflow gửi: màn hình hiện "đang gửi" ngay, khỏi bấm lại trong lúc workflow chưa kịp khoá dòng.
const markSending = (r) => {
  r.status = 'posting';
  r.posted_at = $now.toISO();
  version++;
};
const retry = (r) => {
  r.status = 'pending';
  r.note = cut(`🔁 Gửi lại lúc ${$now.toFormat('HH:mm dd/MM')}${r.note ? ` · trước đó: ${r.note}` : ''}`, 500);
  version++;
  ops.push({ op: 'retry', id: r.id, note: r.note });
};
const setFlag = (key, value) => {
  flags[key] = value;
  version++;
  ops.push({ op: 'flag', key, value, at: $now.toISO() });
};
// Lý do chưa gửi được video kế tiếp (của cả kênh, hoặc của một truyện), hoặc null khi gửi được.
const blocker = (p, job) => {
  const busy = rows.filter((r) => platform(r) === p).find(sending);
  if (busy) return `⏳ Đang gửi ${label(busy)} lên ${P[p].name}, chờ tin báo của bot.`;
  if (p === 'tiktok' && inboxToday().length) return `📥 ${label(inboxToday()[0])} vẫn nằm trong hộp thư TikTok. Đăng xong bấm ✅ rồi hãy gửi tiếp.`;
  if (nextOf(p, job)) return null;
  if (!pendingOf(p, job).length) return job ? `📭 ${nameOf(job)} hết video ${P[p].name} chờ đăng.` : `📭 Hết video ${P[p].name} chờ đăng.`;
  const pend = pendingOf(p, job).filter((r) => p === 'youtube' || ttStarted(r.job_id));
  if (!pend.length) {
    if (job) return `🎵 TikTok của ${nameOf(job)} ${ttFlag(job) === 'off' ? 'đang dừng' : 'chưa bắt đầu'}.`;
    return '🎵 Chưa có truyện nào đang chạy TikTok: chọn truyện trong 📚 Bộ truyện rồi bấm Bắt đầu TikTok.';
  }
  const later = pend.find((r) => !due(r));
  if (later) return `🕒 ${label(later)} hẹn đăng lúc ${when(at(later.scheduled_at))}.`;
  return `📥 ${label(pend[0])} chờ các phần khác đăng xong (phần đang lỗi thì gửi lại hoặc bỏ qua).`;
};
const tiktokNow = (job, done) => {
  const why = blocker('tiktok', job);
  if (why) return why;
  const next = nextOf('tiktok', job);
  runTikTok = { job_id: job ?? '' };
  notice.push(`⏩ ${done ? `${done} ` : ''}Đang gửi ${esc(label(next))} vào hộp thư TikTok, chờ 1–5 phút.`);
  markSending(next);
  return null;
};

// ── Đọc yêu cầu ────────────────────────────────────────────────────────────────
// Nút dưới tin video TikTok: posted|id, skip|id, postnext|id, next(|id), done. Nút của trang quản lý: <màn hình>|<việc>|<đối tượng>.
const LEGACY = { posted: 'ok', skip: 'skip', postnext: 'oknext', next: 'next', done: 'done' };
// Màn hình cũ (trước khi quản lý theo bộ truyện) mở về danh sách truyện.
const ALIAS = { tt: 'home', yt: 'home' };
const SCREENS = ['home', 'st', 'err', 'set', 'fin', 'help', 'msg'];
// "/menu@ten_bot" → "menu", "📚 Bộ truyện" → "botruyen"
const plain = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').replace(/[đĐ]/g, 'd').toLowerCase().replace(/[^a-z0-9]/g, '');
const COMMANDS = {
  start: 'home', menu: 'home', truyen: 'home', botruyen: 'home', tongquan: 'home', trangchu: 'home', tiktok: 'home', youtube: 'home',
  loi: 'err', videoloi: 'err', lich: 'set', lichtudong: 'set', xong: 'fin', daxong: 'fin', giup: 'help', help: 'help', huongdan: 'help',
};

let ctx = 'help';
let action = '';
let arg = '';
let command = '';
if (q) {
  const [a, b = '', c = ''] = String(q.data ?? '').split('|');
  [ctx, action, arg] = own(LEGACY, a) ? ['msg', own(LEGACY, a), b] : [own(ALIAS, a) ?? a, b, c];
} else {
  const text = String(m.text ?? '').trim();
  command = plain(text.startsWith('/') ? text.split(/[\s@]/)[0] : text);
  ctx = own(COMMANDS, command) ?? 'help';
}
// Truyện của màn hình truyện: đối tượng là job_id, hoặc id một video của truyện đó.
const job = ctx === 'st' ? (byJob.has(arg) ? arg : byId(arg)?.job_id ?? null) : null;
const page = ['home', 'fin'].includes(ctx) ? Math.max(1, Number(arg) || 1) : 1;

const STATUS = { pending: 'chờ đăng', posting: 'đang gửi', inbox: 'nằm trong hộp thư TikTok', posted: 'đã đăng', skipped: 'đã bỏ qua', error: 'lỗi', removed: 'đã gỡ' };
// Màn hình hỏi lại trước khi làm việc khó quay lại.
let confirm = null;
// Nút dưới tin video hoặc tin báo: chỉ đổi hàng nút của tin đó.
let markup = null;
const keyboard = q?.message?.reply_markup?.inline_keyboard ?? [];
const canNext = keyboard.flat().some((btn) => String(btn.callback_data ?? '').startsWith('postnext|'));
const isNext = (btn) => String(btn.callback_data ?? '').split('|')[0] === 'next';

if (readError) {
  answer = 'Không đọc được Google Sheet';
} else if (q && !SCREENS.includes(ctx)) {
  answer = 'Nút này đã cũ, gõ /menu để mở trang quản lý';
  ctx = '';
} else if (ctx === 'st' && !job) {
  answer = 'Không tìm thấy truyện này trong Sheet';
  ctx = 'home';
} else if (['ttstart', 'ttstartok', 'ttstop', 'ttnext', 'skipall', 'skipallok', 'retryjob'].includes(action) && !job) {
  answer = 'Nút này đã cũ, gõ /menu để mở trang quản lý';
} else if (action === 'ok' || action === 'oknext' || action === 'skip') {
  const r = byId(arg);
  if (!r) answer = 'Không tìm thấy video này trong Sheet';
  else if (r.status === 'removed') answer = 'Video này đã gỡ khỏi truyện';
  else if (sending(r)) answer = 'Video này đang được gửi, chờ tin báo của bot';
  else if (action === 'skip' && r.status === 'posted') answer = 'Video này đã đăng rồi, không bỏ qua được';
  else {
    const status = action === 'skip' ? 'skipped' : 'posted';
    if (r.status === status) answer = `Video này đã ghi là ${STATUS[status]} rồi`;
    else {
      setStatus(r, status);
      answer = status === 'posted' ? 'Đã ghi: đã đăng' : 'Đã ghi: bỏ qua';
    }
    notice.push(`${status === 'posted' ? '✅' : '⏭'} ${esc(label(r))}: ${STATUS[status]}`);
    const done = `${status === 'posted' ? '✅ Đã đăng' : '⏭ Đã bỏ qua'} lúc ${status === 'posted' && at(r.posted_at) ? when(at(r.posted_at)) : clock}`;
    // Gửi tiếp phần sau của chính truyện này; truyện hết phần thì sang truyện khác đang chạy TikTok.
    const nextBtn = [{ text: '⏩ Gửi video tiếp ngay', callback_data: `next|${r.id}` }];
    if (action === 'oknext') {
      const blocked = tiktokNow(nextOf('tiktok', r.job_id) ? r.job_id : null);
      if (blocked) {
        notice.push(esc(blocked));
        answer = `${answer}. ${blocked}`;
        markup = [[{ text: done, callback_data: 'done' }], nextBtn];
      } else {
        answer = `${answer}. Đang gửi video tiếp theo…`;
        markup = [[{ text: `${done}, đang gửi tiếp`, callback_data: 'done' }]];
      }
    } else {
      markup = [[{ text: done, callback_data: 'done' }], ...(canNext ? [nextBtn] : [])];
    }
  }
} else if (action === 'next' || action === 'ttnext') {
  // ⏩ dưới tin video: phần sau của truyện của video đó (nút cũ không có id thì truyện đang chạy cũ nhất).
  const from = action === 'ttnext' ? job : byId(arg)?.job_id ?? null;
  const why = tiktokNow(from && nextOf('tiktok', from) ? from : action === 'ttnext' ? job : null);
  if (why) {
    answer = why;
    notice.push(esc(why));
  } else {
    answer = 'Đang gửi video tiếp theo, chờ 1–5 phút';
    markup = [...keyboard.filter((row) => !row.some(isNext)), [{ text: `⏩ Đã gửi tiếp lúc ${clock}`, callback_data: 'done' }]];
  }
} else if (action === 'ttstart' && !ytDone(job)) {
  const resume = ttFlag(job) === 'off';
  confirm = {
    lines: [
      `🎵 <b>${resume ? 'Chạy tiếp' : 'Bắt đầu'} TikTok cho ${esc(nameOf(job))}?</b>`, '',
      'YouTube của truyện này chưa đăng xong. Đăng TikTok trước thì người xem chưa tìm được bản đầy đủ trên YouTube.',
    ],
    rows: [[{ text: `✅ Vẫn ${resume ? 'chạy tiếp' : 'bắt đầu'}`, callback_data: `st|ttstartok|${job}` }, { text: '↩️ Thôi', callback_data: `st|view|${job}` }]],
  };
} else if (action === 'ttstart' || action === 'ttstartok') {
  const verb = ttFlag(job) === 'off' ? 'Đã chạy tiếp' : 'Đã bắt đầu';
  setFlag(`tiktok:${job}`, 'on');
  answer = `${verb} TikTok`;
  const why = tiktokNow(job, `${verb} TikTok cho ${esc(nameOf(job))}.`);
  if (why) {
    notice.push(`🎵 ${verb} TikTok cho ${esc(nameOf(job))}. ${esc(why)}`,
      isAuto('tiktok') ? 'Lượt tự động kế tiếp sẽ gửi tiếp.' : 'Lịch TikTok đang tạm dừng: bấm ⏩ Gửi phần tiếp khi muốn gửi.');
  } else answer = `${verb}, đang gửi phần kế tiếp…`;
} else if (action === 'ttstop') {
  setFlag(`tiktok:${job}`, 'off');
  answer = 'Đã dừng TikTok của truyện này';
  notice.push(`⏸ Đã dừng TikTok của ${esc(nameOf(job))}: không gửi thêm phần nào cho tới khi bấm Chạy tiếp.`);
} else if (action === 'ytask' || action === 'ytpost') {
  // Ở màn hình truyện: video YouTube đầu tiên còn chờ của truyện đó (bỏ qua giờ hẹn). Nút cũ không có truyện: video kế tiếp của kênh.
  const target = job ? pendingOf('youtube', job)[0] ?? null : nextOf('youtube');
  const busy = rows.filter((r) => platform(r) === 'youtube').find(sending);
  const why = busy ? `⏳ Đang đăng ${label(busy)} lên YouTube, chờ tin báo của bot.`
    : !target ? (job ? `📭 ${nameOf(job)} không còn video YouTube chờ đăng.` : blocker('youtube')) : null;
  if (why) {
    answer = why;
    notice.push(esc(why));
  } else if (action === 'ytask') {
    const back = job ? `st|view|${job}` : 'home';
    confirm = {
      lines: [
        '▶️ <b>Đăng ngay lên YouTube?</b>', '',
        `📖 ${esc(label(target))}`,
        `🎬 ${esc(cut(target.post_title || target.title, 100))}`,
        `⏱ ${length(target.duration_sec)}`, '',
        'Video được tải lên kênh trong vài phút, xong bot nhắn link.',
      ],
      rows: [[{ text: '✅ Đăng ngay', callback_data: `${job ? 'st' : 'home'}|ytpost${job ? `|${job}` : ''}` }, { text: '↩️ Thôi', callback_data: back }]],
    };
  } else {
    runYouTube = { id: target.id };
    answer = 'Đang đăng lên YouTube…';
    notice.push(`⏳ Đang đăng ${esc(label(target))} lên YouTube. Xong bot sẽ nhắn link (video dài có thể mất vài chục phút).`);
    markSending(target);
  }
} else if (action === 'retry' || action === 'retryall' || action === 'retryjob') {
  const list = action === 'retryall' ? problems() : action === 'retryjob' ? rowsOf(job).filter((r) => r.status === 'error' || stuck(r)) : [byId(arg)].filter(Boolean);
  const can = list.filter((r) => r.status === 'error' || stuck(r));
  can.forEach(retry);
  if (!list.length) answer = action === 'retry' ? 'Không tìm thấy video này trong Sheet' : 'Không có video lỗi';
  else if (!can.length) answer = `Video này đang ở trạng thái "${STATUS[list[0].status] ?? list[0].status}", không cần gửi lại`;
  else {
    answer = can.length > 1 ? `Đã đặt lại ${can.length} video chờ gửi` : 'Đã đặt lại chờ gửi';
    notice.push(`🔁 ${can.length > 1 ? `${can.length} video` : esc(label(can[0]))} đã về hàng chờ.`);
    // Lượt tự động chỉ gửi TikTok khi lịch đang bật và TikTok của truyện đang chạy; YouTube thì không tự đăng. Không gửi được thì nói nút nào gửi.
    for (const r of can.slice(0, 3)) {
      const p = platform(r);
      if (p === 'tiktok' && !ttStarted(r.job_id)) {
        notice.push(`TikTok của ${esc(nameOf(r.job_id))} ${ttFlag(r.job_id) === 'off' ? 'đang dừng: bấm ▶️ Chạy tiếp TikTok' : 'chưa bắt đầu: bấm 🎵 Bắt đầu TikTok'} ở màn hình truyện để gửi.`);
      } else if (p === 'youtube') {
        notice.push(`YouTube không tự đăng: bấm ▶️ Đăng YouTube ngay ở màn hình truyện${isAuto('youtube') ? ', hoặc bấm ở tin nhắc lúc 21h' : ''}.`);
      } else if (!isAuto(p)) {
        notice.push('Lịch TikTok đang tạm dừng: bấm ⏩ Gửi phần tiếp ở màn hình truyện để gửi.');
      }
    }
    if (notice.length === 1) notice[0] += ' Lượt tự động kế tiếp sẽ gửi.';
    markup = [[{ text: `🔁 Đã đặt lại chờ gửi lúc ${clock}`, callback_data: 'done' }]];
  }
} else if (action === 'skipall') {
  const left = rowsOf(job).filter((r) => ['pending', 'error'].includes(r.status));
  confirm = {
    lines: [
      `⏭ <b>Bỏ cả truyện ${esc(nameOf(job))}?</b>`, '',
      `${left.length} video chưa đăng (YouTube và TikTok) sẽ được ghi là bỏ qua, không gửi nữa. Video đang nằm trong hộp thư TikTok giữ nguyên.`,
    ],
    rows: [[{ text: '✅ Bỏ cả truyện', callback_data: `st|skipallok|${job}` }, { text: '↩️ Thôi', callback_data: `st|view|${job}` }]],
  };
} else if (action === 'skipallok') {
  const left = rowsOf(job).filter((r) => ['pending', 'error'].includes(r.status));
  left.forEach((r) => setStatus(r, 'skipped'));
  answer = `Đã bỏ ${left.length} video`;
  notice.push(`⏭ Đã bỏ ${left.length} video chưa đăng của ${esc(nameOf(job))}.`);
} else if (action === 'auto') {
  const [p, value] = arg.split('.');
  if (!own(P, p) || !['on', 'off'].includes(value)) answer = 'Nút này đã cũ';
  else {
    setFlag(`${p}_auto`, value);
    answer = value === 'off' ? `Đã tạm dừng lịch ${P[p].name}` : `Đã bật lại lịch ${P[p].name}`;
    notice.push(value === 'off'
      ? `⏸ Đã tạm dừng lịch ${P[p].name}. Nút ${p === 'tiktok' ? '⏩ Gửi phần tiếp' : '▶️ Đăng YouTube ngay'} trong từng truyện vẫn dùng được.`
      : `▶️ Đã bật lại lịch ${P[p].name} (${esc(P[p].schedule)}).`);
  }
} else if (action === 'done') {
  answer = 'Nút này đã xử lý rồi';
} else if (action === 'refresh') {
  answer = `Đã cập nhật lúc ${clock}`;
}

// ── Màn hình ───────────────────────────────────────────────────────────────────
const btn = (text, data) => ({ text, callback_data: data });
const ICON = { pending: '⏳', posting: '📤', inbox: '📥', posted: '✅', skipped: '⏭', error: '❌' };
const PAGE = 8;
const latestPost = (list) => list.map((r) => at(r.posted_at)).filter(Boolean).sort((a, b) => b - a)[0] ?? null;
const autoText = (p) => (isAuto(p) ? '▶️' : '⏸');
const pager = (screen, pg, pages) => (pages > 1 ? [[
  ...(pg > 1 ? [btn('◀️ Trang trước', `${screen}|page|${pg - 1}`)] : []),
  ...(pg < pages ? [btn('Trang sau ▶️', `${screen}|page|${pg + 1}`)] : []),
]] : []);

// Một dòng tóm tắt YouTube và TikTok của truyện cho danh sách.
const ytBrief = (job) => {
  const list = rowsOf(job, 'youtube');
  if (!list.length) return '▶️ không có YouTube';
  const posted = list.filter((r) => r.status === 'posted');
  if (list.some((r) => r.status === 'error' || stuck(r))) return '▶️ ❌ lỗi';
  if (list.some(sending)) return '▶️ đang đăng';
  if (list.every((r) => FINAL.includes(r.status))) {
    return posted.length ? `▶️ ✅${latestPost(posted) ? ` ${when(latestPost(posted))}` : ''}` : '▶️ ⏭ bỏ qua';
  }
  const count = list.length > 1 ? ` ${posted.length}/${list.length}` : '';
  return `▶️ chờ đăng${count}${nextOf('youtube')?.job_id === job ? ' (kế tiếp)' : ''}`;
};
const ttBrief = (job) => {
  const list = rowsOf(job, 'tiktok');
  if (!list.length) return '🎵 không có TikTok';
  const parts = list.filter((r) => r.kind !== 'full');
  const doneParts = parts.filter((r) => FINAL.includes(r.status)).length;
  const count = `${doneParts}/${parts.length}`;
  if (list.some((r) => r.status === 'error' || stuck(r))) return `🎵 ❌ lỗi · ${count}`;
  if (list.every((r) => FINAL.includes(r.status))) return list.some((r) => r.status === 'posted') ? '🎵 ✅ xong' : '🎵 ⏭ bỏ qua';
  const inbox = list.find((r) => r.status === 'inbox');
  if (inbox) return `🎵 ${count} · ${partName(inbox)} trong hộp thư`;
  if (list.some(sending)) return `🎵 ${count} · đang gửi`;
  if (!ttStarted(job)) return ttFlag(job) === 'off' ? `🎵 ⏸ đã dừng · ${count}` : '🎵 chưa bắt đầu';
  return doneParts === parts.length ? `🎵 ${count} · còn trọn bộ` : `🎵 ${count} phần`;
};

const home = () => {
  const open = jobs.filter(isOpen);
  const finished = jobs.length - open.length;
  const pages = Math.max(1, Math.ceil(open.length / PAGE));
  const pg = Math.min(page, pages);
  const shown = open.slice((pg - 1) * PAGE, pg * PAGE);
  const bad = problems().length;
  const lines = [
    `📚 <b>Bộ truyện</b> · ${clock}`,
    `<i>Lịch: YouTube ${autoText('youtube')} ${esc(P.youtube.schedule)} · TikTok ${autoText('tiktok')} ${esc(P.tiktok.schedule)}</i>`,
  ];
  if (!open.length) lines.push('', 'Không có truyện nào đang chờ đăng.');
  shown.forEach((j, i) => lines.push('', `${(pg - 1) * PAGE + i + 1}. <b>${esc(nameOf(j))}</b>`, `${ytBrief(j)} · ${ttBrief(j)}`));
  if (pages > 1) lines.push('', `Trang ${pg}/${pages}`);
  lines.push('', bad ? `⚠️ <b>${bad} video lỗi hoặc bị kẹt</b>` : '✅ Không có video lỗi');
  return { lines, rows: [
    ...shown.map((j, i) => [btn(`${(pg - 1) * PAGE + i + 1}. ${cut(nameOf(j), 40)}`, `st|view|${j}`)]),
    ...pager('home', pg, pages),
    [btn(`⚠️ Video lỗi${bad ? ` (${bad})` : ''}`, 'err'), btn('⚙️ Lịch tự động', 'set')],
    [btn(`📦 Đã xong${finished ? ` (${finished})` : ''}`, 'fin'), btn('🔄 Làm mới', `home|refresh|${pg}`)],
  ] };
};

const rowState = (r) => {
  const p = platform(r);
  if (r.status === 'pending') {
    if (!due(r)) return `hẹn ${when(at(r.scheduled_at))}`;
    if (p === 'youtube') return nextOf('youtube')?.id === r.id ? 'chờ đăng, kế tiếp' : 'chờ đăng';
    if (!ttStarted(r.job_id)) return ttFlag(r.job_id) === 'off' ? 'đã dừng' : 'chờ bắt đầu';
    return nextOf('tiktok')?.id === r.id ? 'chờ gửi, kế tiếp' : r.kind === 'full' && partsLeft(r) ? 'gửi sau phần cuối' : 'chờ gửi';
  }
  if (r.status === 'posting') return sending(r) ? `đang gửi từ ${when(at(r.posted_at))}` : `kẹt từ ${when(at(r.posted_at))}`;
  if (r.status === 'inbox') return `trong hộp thư từ ${when(at(r.posted_at))}`;
  if (r.status === 'posted') return `đã đăng${at(r.posted_at) ? ` ${when(at(r.posted_at))}` : ''}`;
  if (r.status === 'error') return `lỗi: ${esc(cut(r.note || 'không rõ', 80))}`;
  return STATUS[r.status] ?? esc(r.status);
};

const story = () => {
  const yt = rowsOf(job, 'youtube');
  const tt = rowsOf(job, 'tiktok');
  const inbox = tt.find((r) => r.status === 'inbox');
  const bad = rowsOf(job).filter((r) => r.status === 'error' || stuck(r));
  const lines = [`📖 <b>${esc(nameOf(job))}</b> · ${clock}`, '', '▶️ <b>YouTube</b>'];
  if (!yt.length) lines.push('Truyện này không có video YouTube.');
  yt.forEach((r) => lines.push(
    `${ICON[r.status] ?? '•'} ${r.part ? `Phần ${r.part}/${r.total_parts} · ` : fullName(r) ? 'Trọn bộ · ' : ''}${length(r.duration_sec)} · ${rowState(r)}${r.post_url ? `\n   ${esc(r.post_url)}` : ''}`,
  ));
  const ttState = !tt.length ? '' : tt.every((r) => FINAL.includes(r.status)) ? 'xong'
    : ttStarted(job) ? 'đang chạy' : ttFlag(job) === 'off' ? 'đã dừng' : 'chưa bắt đầu';
  lines.push('', `🎵 <b>TikTok</b>${ttState ? ` · ${ttState}` : ''}`);
  if (!tt.length) lines.push('Truyện này không có video TikTok.');
  tt.forEach((r) => lines.push(`${ICON[r.status] ?? '•'} ${r.part ? `Phần ${r.part}/${r.total_parts}` : 'Trọn bộ'} · ${rowState(r)}`));
  const open = rowsOf(job).some((r) => ['pending', 'error'].includes(r.status));
  const ttLeft = tt.some((r) => r.status === 'pending');
  const ttBusy = rows.some((r) => platform(r) === 'tiktok' && sending(r));
  return { lines, rows: [
    ...(pendingOf('youtube', job).length && !yt.some(sending) ? [[btn('▶️ Đăng YouTube ngay', `st|ytask|${job}`)]] : []),
    ...(ttLeft && !ttStarted(job) ? [[btn(ttFlag(job) === 'off' ? '▶️ Chạy tiếp TikTok' : '🎵 Bắt đầu TikTok', `st|ttstart|${job}`)]] : []),
    ...(ttLeft && ttStarted(job) ? [[...(ttBusy ? [] : [btn('⏩ Gửi phần tiếp ngay', `st|ttnext|${job}`)]), btn('⏸ Dừng TikTok', `st|ttstop|${job}`)]] : []),
    ...(inbox ? [[btn(`✅ Đã đăng ${partName(inbox)}`, `st|ok|${inbox.id}`), btn(`⏭ Bỏ ${partName(inbox)}`, `st|skip|${inbox.id}`)]] : []),
    ...(bad.length ? [[btn(`🔁 Gửi lại ${bad.length} video lỗi`, `st|retryjob|${job}`)]] : []),
    ...(open ? [[btn('⏭ Bỏ cả truyện', `st|skipall|${job}`)]] : []),
    [btn('↩️ Bộ truyện', 'home'), btn('🔄 Làm mới', `st|refresh|${job}`)],
  ] };
};

const errors = () => {
  const bad = problems();
  const lines = [`⚠️ <b>Video lỗi</b> · ${clock}`];
  if (!bad.length) lines.push('', '✅ Không có video lỗi hay bị kẹt.');
  bad.slice(0, 8).forEach((r, i) => {
    const p = platform(r);
    lines.push('', `${i + 1}. ${p === 'youtube' ? '▶️' : '🎵'} <b>${esc(label(r))}</b>`);
    lines.push(r.status === 'error'
      ? `❌ ${esc(cut(r.note || 'Lỗi không rõ', 200))}`
      : `⏳ Kẹt ở "đang gửi"${r.posted_at ? ` từ ${when(at(r.posted_at))}` : ''}: xem ${P[p].where} trước, video có thể đã lên rồi.`);
  });
  if (bad.length > 8) lines.push('', `… và ${bad.length - 8} video nữa`);
  return { lines, rows: [
    ...bad.slice(0, 8).map((r, i) => [btn(`🔁 Gửi lại ${i + 1}`, `err|retry|${r.id}`), btn(`⏭ Bỏ ${i + 1}`, `err|skip|${r.id}`)]),
    ...(bad.length > 1 ? [[btn(`🔁 Gửi lại cả ${bad.length} video`, 'err|retryall')]] : []),
    [btn('↩️ Bộ truyện', 'home'), btn('🔄 Làm mới', 'err|refresh')],
  ] };
};

const settings = () => ({
  lines: [
    `⚙️ <b>Lịch tự động</b> · ${clock}`, '',
    `▶️ <b>YouTube</b>: ${esc(P.youtube.schedule)}, truyện cũ trước · ${isAuto('youtube') ? '▶️ đang bật' : '⏸ đang tạm dừng'}`,
    `🎵 <b>TikTok</b>: ${esc(P.tiktok.schedule)}, chỉ các truyện đã bấm Bắt đầu TikTok · ${isAuto('tiktok') ? '▶️ đang bật' : '⏸ đang tạm dừng'}`, '',
    'Tạm dừng thì lịch không gửi, không nhắc; nút Đăng YouTube ngay và Gửi phần tiếp trong từng truyện vẫn dùng được.',
  ],
  rows: [
    ...['youtube', 'tiktok'].map((p) => [btn(`${isAuto(p) ? '⏸ Tạm dừng' : '▶️ Bật lại'} ${P[p].name}`, `set|auto|${p}.${isAuto(p) ? 'off' : 'on'}`)]),
    [btn('↩️ Bộ truyện', 'home'), btn('🔄 Làm mới', 'set|refresh')],
  ],
});

const finished = () => {
  const list = jobs.filter((j) => !isOpen(j)).sort((a, b) => (latestPost(rowsOf(b)) ?? 0) - (latestPost(rowsOf(a)) ?? 0));
  const pages = Math.max(1, Math.ceil(list.length / PAGE));
  const pg = Math.min(page, pages);
  const shown = list.slice((pg - 1) * PAGE, pg * PAGE);
  const lines = [`📦 <b>Truyện đã đăng xong</b> · ${clock}`];
  if (!list.length) lines.push('', 'Chưa có truyện nào đăng xong.');
  shown.forEach((j, i) => {
    const url = rowsOf(j, 'youtube').find((r) => r.status === 'posted' && r.post_url)?.post_url;
    lines.push('', `${(pg - 1) * PAGE + i + 1}. <b>${esc(nameOf(j))}</b>`, `${ytBrief(j)} · ${ttBrief(j)}${url ? `\n${esc(url)}` : ''}`);
  });
  if (pages > 1) lines.push('', `Trang ${pg}/${pages}`);
  return { lines, rows: [
    ...shown.map((j, i) => [btn(`${(pg - 1) * PAGE + i + 1}. ${cut(nameOf(j), 40)}`, `st|view|${j}`)]),
    ...pager('fin', pg, pages),
    [btn('↩️ Bộ truyện', 'home'), btn('🔄 Làm mới', `fin|refresh|${pg}`)],
  ] };
};

const help = () => ({ lines: [
  'ℹ️ <b>Cách dùng bot</b>',
  '',
  '📚 <b>Bộ truyện</b>: các truyện đang đăng, mỗi truyện một nút. Trong truyện: ▶️ Đăng YouTube ngay, 🎵 Bắt đầu TikTok (TikTok của truyện chỉ gửi sau khi bấm), ⏩ Gửi phần tiếp, ⏸ Dừng TikTok, ⏭ Bỏ cả truyện.',
  '▶️ YouTube không tự đăng: 21h mỗi ngày bot nhắc video kế tiếp, bấm nút trong tin nhắc mới đăng. 🎵 TikTok tự gửi 2 giờ một lần.',
  '⚠️ <b>Video lỗi</b>: gửi lại hoặc bỏ qua video bị lỗi, bị kẹt.',
  '⚙️ <b>Lịch tự động</b>: tạm dừng hoặc bật lại lịch YouTube, TikTok.',
  '📦 <b>Đã xong</b>: các truyện đã đăng hết.',
  '',
  'Nút ✅ ⏭ ⏩ dưới tin video TikTok dùng như cũ. Gõ /start để hiện lại bàn phím. Tin của bot được dọn lúc 0h mỗi ngày.',
], rows: [[btn('📚 Bộ truyện', 'home')]] });

const sheetDown = (screen) => ({
  lines: [
    '❌ <b>Không đọc được Google Sheet</b>', '',
    `<i>${esc(cut(errorText(readError), 500))}</i>`, '',
    'Thử lại sau ít phút. Lỗi còn hoài thì mở n8n kiểm tra credential Google Sheets.',
  ],
  rows: [[btn('🔄 Thử lại', `${['msg', 'st', ''].includes(screen) ? 'home' : screen}|refresh`)]],
});

const VIEWS = { home, st: story, err: errors, set: settings, fin: finished, help };
const render = (screen) => {
  const view = readError ? sheetDown(screen) : confirm ?? own(VIEWS, screen)?.() ?? help();
  const lines = notice.length && !readError && !confirm ? [...notice, '', ...view.lines] : view.lines;
  return {
    chat_id: chatId, parse_mode: 'HTML', text: lines.join('\n').slice(0, 4096),
    link_preview_options: { is_disabled: true }, reply_markup: { inline_keyboard: view.rows },
  };
};

// ── Trả lời ────────────────────────────────────────────────────────────────────
const tg = (method, payload) => ops.push({ op: 'tg', method, payload });
if (q) {
  tg('answerCallbackQuery', { callback_query_id: q.id, text: cut(answer, 190) });
  if (ctx === 'msg') {
    if (markup) tg('editMessageReplyMarkup', { chat_id: chatId, message_id: q.message.message_id, reply_markup: { inline_keyboard: markup } });
  } else if (SCREENS.includes(ctx)) {
    const { chat_id, ...view } = render(ctx);
    tg('editMessageText', { chat_id, message_id: q.message.message_id, ...view });
  }
} else {
  if (command === 'start') {
    tg('setMyCommands', { commands: [
      { command: 'menu', description: 'Bộ truyện: tình hình đăng từng truyện' },
      { command: 'loi', description: 'Video lỗi, gửi lại hoặc bỏ qua' },
      { command: 'lich', description: 'Lịch tự động YouTube, TikTok' },
      { command: 'xong', description: 'Truyện đã đăng xong' },
      { command: 'giup', description: 'Cách dùng bot' },
    ] });
    // Tin chào giữ bàn phím quản lý nên không ghi vào TelegramLog (không bị dọn lúc 0h).
    tg('sendMessage', { chat_id: chatId, text: '👋 Đã bật bàn phím quản lý bên dưới. Bấm một nút hoặc gõ /menu.', reply_markup: {
      keyboard: [[{ text: '📚 Bộ truyện' }, { text: '⚠️ Video lỗi' }], [{ text: '⚙️ Lịch tự động' }, { text: '📦 Đã xong' }]],
      is_persistent: true, resize_keyboard: true,
    } });
  }
  // Xoá tin lệnh của bạn cho cuộc trò chuyện gọn, chỉ còn màn hình bot trả lời.
  if (own(COMMANDS, command)) tg('deleteMessage', { chat_id: chatId, message_id: m.message_id });
  ops.push({ op: 'tgsend', payload: render(ctx) });
}
if (runTikTok) ops.push({ op: 'tiktok', ...runTikTok });
if (runYouTube) ops.push({ op: 'youtube', ...runYouTube });
return ops.map((json) => ({ json }));

// Không chạy được workflow gửi video (chưa Publish, thiếu credential…): báo trong Telegram thay vì im lặng.
const cfg = $('Cấu hình').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const which = $('Đăng YouTube ngay').isExecuted ? 'YouTube - Đăng video' : 'TikTok - Gửi video vào hộp thư';
const e = $input.first().json.error;
const why = String(e?.message ?? e ?? 'Lỗi không rõ').slice(0, 500);
return [{ json: { payload: { chat_id: cfg.chat_id, parse_mode: 'HTML', text: [
  `❌ <b>Không chạy được workflow "${which}"</b>`,
